// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        vm.assume(target != address(0) && target != address(c));
        uint256 initialCount = c.depositsCount();
        address(c).call{value: 1 ether}("");
        vm.prank(c.owner());
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.sendMoney.selector, target, value, data));
        if (ok) {
            assertTrue(c.depositsCount() >= initialCount + 1);
        } else {
            assertTrue(c.depositsCount() >= initialCount);
        }
    }
}

